import{_ as a,a0 as s,w as r,s as u,ao as o,I as i,x as n,a1 as l,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"安裝 Linux，只需三步 | LCTT x X-CMD","titleTemplate":false,"description":"安裝 Linux，只需三步 | LCTT (202103) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安裝 Linux，只需三步 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安裝 Linux，只需三步 | LCTT (202103) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202103/20210216 How to install Linux in 3 steps","title":"安裝 Linux，只需三步","tag":"202103","desc":""},"relativePath":"202103/20210216 How to install Linux in 3 steps.md","filePath":"[post].md"}'),d={name:"202103/20210216 How to install Linux in 3 steps.md"};function m(x,t,L,f,T,g){const e=s("Link");return r(),u("div",null,[t[33]||(t[33]=o('<h1 id="安裝-linux-只需三步" tabindex="-1">安裝 Linux，只需三步 <a class="header-anchor" href="#安裝-linux-只需三步" aria-label="Permalink to “安裝 Linux，只需三步”">​</a></h1><blockquote><p>操作系統的安裝看似神秘，但其實很簡單。以下是成功安裝 Linux 的步驟。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202103/01/084538it1188e8zeepgzyb.jpg" alt=""></p><p>在 2021 年，有更多讓人們喜歡 Linux 的理由。在這個系列中，我將分享 21 種使用 Linux 的不同理由。下面是如何安裝 Linux。</p><p>安裝一個操作系統（OS）總是令人生畏。對大多數人來説，這是一個難題。安裝操作系統不能從操作系統內部進行，因為它要麼沒有被安裝，要麼即將被另一個操作系統取代，那麼它是如何發生的呢？更糟糕的是，它通常會涉及到硬盤格式、安裝位置、時區、用户名、密碼等一系列你通常不會想到的混亂問題。Linux 發行版知道這一點，所以它們多年來一直在努力將你在操作系統安裝程序中花費的時間減少到最低限度。</p><h3 id="安裝時發生了什麼" tabindex="-1">安裝時發生了什麼 <a class="header-anchor" href="#安裝時發生了什麼" aria-label="Permalink to “安裝時發生了什麼”">​</a></h3><p>無論你安裝的是一個應用程序還是整個操作系統，<em>安裝</em>的過程只是將文件從一種媒介複製到另一種媒介的一種花哨方式。不管是什麼用户界面，還是用動畫將安裝過程偽裝成多麼高度專業化的東西，最終都是一回事：曾經存儲在光盤或驅動器上的文件被複制到硬盤上的特定位置。</p><p>當安裝的是一個應用程序時，放置這些文件的有效位置被高度限制在你的<em>文件系統</em>或你的操作系統知道它可以使用的硬盤驅動器的部分。這一點很重要，因為它可以將硬盤分割成不同的空間（蘋果公司在本世紀初的 Bootcamp 中使用了這一技巧，允許用户將 macOS 和 Windows 安裝到一個硬盤上，但作為單獨的實體）。當你安裝一個操作系統時，一些特殊的文件會被安裝到硬盤上通常是禁區的地方。更重要的是，至少在默認情況下，你的硬盤上的所有現有數據都會被擦除，以便為新系統騰出空間，所以創建一個備份是<em>必要的</em>。</p><h3 id="安裝程序" tabindex="-1">安裝程序 <a class="header-anchor" href="#安裝程序" aria-label="Permalink to “安裝程序”">​</a></h3>',9)),i("p",null,[t[1]||(t[1]=n("從技術上講，你實際上不需要用安裝程序來安裝應用程序甚至操作系統。不管你信不信，有些人通過掛載一塊空白硬盤、編譯代碼並複製文件來手動安裝 Linux。這是在一個名為 ",-1)),l(e,{href:"http://www.linuxfromscratch.org"},{default:p(()=>[...t[0]||(t[0]=[n("Linux From Scratch（LFS）",-1)])]),_:1}),t[2]||(t[2]=n(" 的項目的幫助下完成的。這個項目旨在幫助愛好者、學生和未來的操作系統設計者更多地瞭解計算機的工作原理以及每個組件執行的功能。這並不是安裝 Linux 的推薦方法，但你會發現，在開源中，通常是這樣的：",-1)),t[3]||(t[3]=i("em",null,"如果",-1)),t[4]||(t[4]=n("有些事情可以做，那麼就有人在做。而這也是一件好事，因為這些小眾的興趣往往會帶來令人驚訝的有用的創新。",-1))]),t[34]||(t[34]=o('<p>假設你不是想對 Linux 進行逆向工程，那麼正常的安裝方式是使用安裝光盤或鏡像。</p><h3 id="_3-個簡單的步驟來安裝-linux" tabindex="-1">3 個簡單的步驟來安裝 Linux <a class="header-anchor" href="#_3-個簡單的步驟來安裝-linux" aria-label="Permalink to “3 個簡單的步驟來安裝 Linux”">​</a></h3><p>當你從一個 Linux 安裝 DVD 或 U 盤啓動時，你會置身於一個最小化的操作環境中，這個環境是為了運行一個或多個有用的應用程序。安裝程序是最主要的應用程序，但由於 Linux 是一個如此靈活的系統，你通常也可以運行標準的桌面應用程序，以在你決定安裝它之前感受一下這個操作系統是什麼樣子的。</p><p>不同的 Linux 發行版有不同的安裝程序界面。下面是兩個例子。</p><p>Fedora Linux 有一個靈活的安裝程序（稱為 Anaconda），能夠進行復雜的系統配置：</p><p><img src="https://opensource.com/sites/default/files/anaconda-installer.png" alt="Fedora 上的 Anaconda 安裝界面"></p><p><em>Fedora 上的 Anaconda 安裝程序</em></p><p>Elementary OS 有一個簡單的安裝程序，主要是為了在個人電腦上安裝而設計的：</p><p><img src="https://opensource.com/sites/default/files/elementary-installer.png" alt="Elementary OS 安裝程序"></p><p><em>Elementary OS 安裝程序</em></p><h4 id="_1、獲取安裝程序" tabindex="-1">1、獲取安裝程序 <a class="header-anchor" href="#_1、獲取安裝程序" aria-label="Permalink to “1、獲取安裝程序”">​</a></h4><p>安裝 Linux 的第一步是下載一個安裝程序。你可以從你選擇嘗試的發行版中獲得一個 Linux 安裝鏡像。</p>',12)),i("ul",null,[i("li",null,[l(e,{href:"http://getfedora.org"},{default:p(()=>[...t[5]||(t[5]=[n("Fedora",-1)])]),_:1}),t[6]||(t[6]=n(" 以率先更新軟件而聞名。",-1))]),i("li",null,[l(e,{href:"http://linuxmint.com"},{default:p(()=>[...t[7]||(t[7]=[n("Linux Mint",-1)])]),_:1}),t[8]||(t[8]=n(" 提供了安裝缺失驅動程序的簡易選項。",-1))]),i("li",null,[l(e,{href:"http://elementary.io"},{default:p(()=>[...t[9]||(t[9]=[n("Elementary",-1)])]),_:1}),t[10]||(t[10]=n(" 提供了一個美麗的桌面體驗和幾個特殊的、定製的應用程序。",-1))])]),i("p",null,[t[12]||(t[12]=n("Linux 安裝程序是 ",-1)),t[13]||(t[13]=i("code",null,".iso",-1)),t[14]||(t[14]=n(" 文件，是 DVD 介質的“藍圖”。如果你還在使用光學介質，你可以把 ",-1)),t[15]||(t[15]=i("code",null,".iso",-1)),t[16]||(t[16]=n(" 文件刻錄到 DVD-R 上，或者你可以把它燒錄到 U 盤上（確保它是一個空的 U 盤，因為當鏡像被燒錄到它上時，它的所有內容都會被刪除）。要將鏡像燒錄到 U 盤上，你可以 ",-1)),l(e,{href:"https://opensource.com/article/18/7/getting-started-etcherio"},{default:p(()=>[...t[11]||(t[11]=[n("使用開源的 Etcher 應用程序",-1)])]),_:1}),t[17]||(t[17]=n("。",-1))]),t[35]||(t[35]=o('<p><img src="https://opensource.com/sites/default/files/etcher_0.png" alt="Etcher 用於燒錄 U 盤"></p><p><em>Etcher 應用程序可以燒錄 U 盤。</em></p><p>現在你可以安裝 Linux 了。</p><h4 id="_2、引導順序" tabindex="-1">2、引導順序 <a class="header-anchor" href="#_2、引導順序" aria-label="Permalink to “2、引導順序”">​</a></h4><p>要在電腦上安裝操作系統，你必須引導到操作系統安裝程序。這對於一台電腦來説並不是常見的行為，因為很少有人這樣做。理論上，你只需要安裝一次操作系統，然後你就會不斷更新它。當你選擇在電腦上安裝不同的操作系統時，你就中斷了這個正常的生命週期。這不是一件壞事。這是你的電腦，所以你有權力對它進行重新規劃。然而，這與電腦的默認行為不同，它的默認行為是開機後立即啓動到硬盤上找到的任何操作系統。</p><p>在安裝 Linux 之前，你必須備份你在目標計算機上的任何數據，因為這些數據在安裝時都會被清除。</p><p>假設你已經將數據保存到了一個外部硬盤上，然後你將它秘密地存放在安全的地方（而不是連接到你的電腦上），那麼你就可以繼續了。</p><p>首先，將裝有 Linux 安裝程序的 U 盤連接到電腦上。打開電腦電源，觀察屏幕上是否有一些如何中斷其默認啓動序列的指示。這通常是像 <code>F2</code>、<code>F8</code>、<code>Esc</code> 甚至 <code>Del</code> 這樣的鍵，但根據你的主板製造商不同而不同。如果你錯過了這個時間窗口，只需等待默認操作系統加載，然後重新啓動並再次嘗試。</p><p>當你中斷啓動序列時，電腦會提示你引導指令。具體來説，嵌入主板的固件需要知道該到哪個驅動器尋找可以加載的操作系統。在這種情況下，你希望計算機從包含 Linux 鏡像的 U 盤啓動。如何提示你這些信息取決於主板製造商。有時，它會直接問你，並配有一個菜單：</p><p><img src="https://opensource.com/sites/default/files/boot-menu.jpg" alt="引導設備菜單"></p><p><em>啓動設備選擇菜單</em></p><p>其他時候，你會被帶入一個簡陋的界面，你可以用來設置啓動順序。計算機通常默認設置為先查看內部硬盤。如果引導失敗，它就會移動到 U 盤、網絡驅動器或光驅。你需要告訴你的計算機先尋找一個 U 盤，這樣它就會繞過自己的內部硬盤驅動器，而引導 U 盤上的 Linux 鏡像。</p><p><img src="https://opensource.com/sites/default/files/bios_1.jpg" alt="BIOS 選擇屏幕"></p><p><em>BIOS 選擇屏幕</em></p><p>起初，這可能會讓人望而生畏，但一旦你熟悉了界面，這就是一個快速而簡單的任務。一旦安裝了Linux，你就不必這樣做了，因為，在這之後，你會希望你的電腦再次從內部硬盤啓動。這是一個很好的技巧，因為在 U 盤上使用 Linux 的關鍵原因，是在安裝前測試計算機的 Linux 兼容性，以及無論涉及什麼操作系統的一般性故障排除。</p><p>一旦你選擇了你的 U 盤作為引導設備，保存你的設置，讓電腦復位，然後啓動到 Linux 鏡像。</p><h4 id="_3、安裝-linux" tabindex="-1">3、安裝 Linux <a class="header-anchor" href="#_3、安裝-linux" aria-label="Permalink to “3、安裝 Linux”">​</a></h4><p>一旦你啓動進入 Linux 安裝程序，就只需通過提示進行操作。</p><p>Fedora 安裝程序 Anaconda 為你提供了一個“菜單”，上面有你在安裝前可以自定義的所有事項。大多數設置為合理的默認值，可能不需要你的互動，但有些則用警示符號標記，表示不能安全地猜測出你的配置，因此需要設置。這些配置包括你想安裝操作系統的硬盤位置，以及你想為賬户使用的用户名。在你解決這些問題之前，你不能繼續進行安裝。</p><p>對於硬盤的位置，你必須知道你要擦除哪個硬盤，然後用你選擇的 Linux 發行版重新寫入。對於只有一個硬盤的筆記本來説，這可能是一個顯而易見的選擇。</p><p><img src="https://opensource.com/sites/default/files/install-harddrive-chooser.png" alt="選擇安裝驅動器的屏幕"></p><p><em>選擇要安裝操作系統的硬盤（本例中只有一個硬盤）。</em></p><p>如果你的電腦裏有不止一個硬盤，而你只想在其中一個硬盤上安裝 Linux，或者你想把兩個硬盤當作一個硬盤，那麼你必須幫助安裝程序瞭解你的目標。最簡單的方法是隻給 Linux 分配一個硬盤，讓安裝程序執行自動分區和格式化，但對於高級用户來説，還有很多其他的選擇。</p><p>你的電腦必須至少有一個用户，所以要為自己創建一個用户賬户。完成後，你可以最後點擊 <strong>Done</strong> 按鈕，安裝 Linux。</p><p><img src="https://opensource.com/sites/default/files/anaconda-done.png" alt="Anaconda 選項完成並準備安裝"></p><p><em>Anaconda 選項已經完成，可以安裝了</em></p><p>其他的安裝程序可能會更簡單，所以你看到的可能與本文中的圖片不同。無論怎樣，除了預裝的操作系統之外，這個安裝過程都是最簡單的操作系統安裝過程之一，所以不要讓安裝操作系統的想法嚇到你。這是你的電腦。你可以、也應該安裝一個你擁有所有權的操作系統。</p><h3 id="擁有你的電腦" tabindex="-1">擁有你的電腦 <a class="header-anchor" href="#擁有你的電腦" aria-label="Permalink to “擁有你的電腦”">​</a></h3><p>最終，Linux 成為了你的操作系統。它是一個由來自世界各地的人們開發的操作系統，其核心是一個：創造一種參與、共同擁有、合作管理的計算文化。如果你有興趣更好地瞭解開源，那麼就請你邁出一步，瞭解它的一個光輝典範 Linux，並安裝它。</p><hr>',30)),i("p",null,[t[19]||(t[19]=n("via: ",-1)),l(e,{href:"https://opensource.com/article/21/2/linux-installation"},{default:p(()=>[...t[18]||(t[18]=[n("https://opensource.com/article/21/2/linux-installation",-1)])]),_:1})]),i("p",null,[t[24]||(t[24]=n("作者：",-1)),l(e,{href:"https://opensource.com/users/seth"},{default:p(()=>[...t[20]||(t[20]=[n("Seth Kenlon",-1)])]),_:1}),t[25]||(t[25]=n(" 選題：",-1)),l(e,{href:"https://github.com/lujun9972"},{default:p(()=>[...t[21]||(t[21]=[n("lujun9972",-1)])]),_:1}),t[26]||(t[26]=n(" 譯者：",-1)),l(e,{href:"https://github.com/wxy"},{default:p(()=>[...t[22]||(t[22]=[n("wxy",-1)])]),_:1}),t[27]||(t[27]=n(" 校對：",-1)),l(e,{href:"https://github.com/wxy"},{default:p(()=>[...t[23]||(t[23]=[n("wxy",-1)])]),_:1})]),i("p",null,[t[30]||(t[30]=n("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[28]||(t[28]=[n("LCTT",-1)])]),_:1}),t[31]||(t[31]=n(" 原創編譯，",-1)),l(e,{href:"https://linux.cn/"},{default:p(()=>[...t[29]||(t[29]=[n("Linux中國",-1)])]),_:1}),t[32]||(t[32]=n(" 榮譽推出",-1))])])}const C=a(d,[["render",m]]);export{S as __pageData,C as default};
